package com.helpinghands.service;
import com.helpinghands.dto.admin.CreateResponderRequest; import com.helpinghands.dto.auth.UserResponse; import com.helpinghands.entity.*; import com.helpinghands.entity.enums.*; import com.helpinghands.exception.*; import com.helpinghands.mapper.UserMapper; import com.helpinghands.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class AdminResponderService { private final UserRepository users; private final EmergencyResponderRepository responders; private final PasswordEncoder encoder; private final UserMapper mapper;
 @Transactional(readOnly=true) public List<UserResponse> list(){return users.findAll().stream().filter(u->u.getRole()==Role.RESPONDER).map(u->mapper.toResponse(u,responders.findByUserId(u.getId()).orElse(null))).toList();}
 @Transactional public UserResponse create(CreateResponderRequest r){if(users.findByEmailIgnoreCase(r.email()).isPresent()) throw new BadRequestException("Email is already in use."); User u=users.save(User.builder().name(r.name().trim()).email(r.email().trim()).phone(r.phone().trim()).passwordHash(encoder.encode(r.password())).role(Role.RESPONDER).active(true).build()); EmergencyResponder e=responders.save(EmergencyResponder.builder().user(u).name(u.getName()).email(u.getEmail()).phone(u.getPhone()).department(r.department()).unitName(r.unitName()).baseLatitude(r.baseLatitude()).baseLongitude(r.baseLongitude()).availabilityStatus(r.availabilityStatus()==null?AvailabilityStatus.AVAILABLE:r.availabilityStatus()).build()); return mapper.toResponse(u,e);}
 @Transactional public UserResponse active(Long id,boolean active){User u=users.findById(id).orElseThrow(()->ResourceNotFoundException.of("User",id)); if(u.getRole()!=Role.RESPONDER) throw new BadRequestException("Not a responder."); u.setActive(active); users.save(u); return mapper.toResponse(u,responders.findByUserId(id).orElse(null));}}
